// AppMetadata captures an application's build-time identity and metadata.
// This includes the application ID, name, version, build number, and optional icon.
//
// Since: 2.5
type AppMetadata struct {
	// ID is the unique application identifier (e.g., "com.example.myapp")
	ID string
	// Name is the human-friendly application name (e.g., "My Application")
	Name string
	// Version is the semantic version string (e.g., "1.0.0")
	Version string
	// Build is the build number
	Build int
	// Icon is the optional application icon resource
	Icon Resource
}

// Lifecycle represents the various phases that an app can transition through.
//
// Since: 2.1
type Lifecycle interface {
	// SetOnEnteredForeground hooks into the app becoming foreground and gaining focus.
