package validation

import (
	"errors"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a validator that requires the input to match one of the provided strings.
// The validator will return nil if the input matches any string in the list, otherwise returns an error.
//
// Since: 2.5
func NewAllStrings(validStrings []string, reason string) fyne.StringValidator {
	return func(text string) error {
		for _, valid := range validStrings {
			if text == valid {
				return nil
			}
		}
		return errors.New(reason)
	}
}

